fn sum(take n: Int, take acc: Int) -> Int {
    if n == 0 { acc } else { sum(n - 1, acc + n) }
}
fn main() -> Int { sum(1000, 0) }

fn f(take n: Int) -> Int { n + 1 }
fn g(take n: Int) -> Int { f(n) + f(n) }
fn main() -> Int { g(3) + g(4) + g(5) }

// indirect-calls — a hot loop calling through a first-class function VALUE
// (ADR-0008 Tier 1), the indirect-call sibling of the `function-calls`
// workload (which measures only direct calls). `step` is a
// `fn(take Int, take Int) -> Int` value: `main` passes the top-level `add` by
// name (the only way to obtain a function value in Tier 1), and `fold` invokes
// it through the indirect-call path once per iteration. The equivalent C peer
// (`benchmarks/runtime/programs/c/indirect-calls.c`) runs the identical loop
// calling through a function pointer, so the comparison isolates the indirect
// dispatch itself: same arithmetic, same iteration count, same exit.
fn add(take a: Int, take b: Int) -> Int {
    a + b
}

// Fold `step` over `reps` iterations, adding 1 each time. Every `step(acc, 1)`
// is an indirect call through the function value — the operation being measured.
fn fold(take reps: Int, take step: fn(take Int, take Int) -> Int) -> Int {
    var acc = 0;
    var i = 0;
    while i < reps {
        acc = step(acc, 1);
        i = i + 1;
    }
    acc
}

fn main() -> Int {
    // 2_000_000 indirect calls through `add`, each contributing 1, so
    // acc = 2_000_000. Observable exit byte = 2_000_000 & 0xff = 128.
    fold(2000000, add)
}

fn fib(take n: Int) -> Int {
    if n < 2 { n } else { fib(n - 1) + fib(n - 2) }
}
fn main() -> Int { fib(20) }

fn lookup(take table: [Int; 8], take i: Usize) -> Int {
    table[i]
}

fn scan(take table: [Int; 8]) -> Int {
    var total = 0;
    for x in table {
        total = total + x;
    }
    total
}

fn probe(take table: [Int; 8]) -> Int {
    lookup(table, 0) + lookup(table, 3) + lookup(table, 7)
}

fn main() -> Int {
    let table = [3, 1, 4, 1, 5, 9, 2, 6];
    var total = 0;
    var round = 0;
    while round < 200 {
        total = total + scan(table) + probe(table);
        round = round + 1;
    }
    total
}

fn line() -> Str {
    "GET /users/42 HTTP/1.1 200 1532"
}

fn count_byte(in text: Str, take target: Int) -> Int {
    var found = 0;
    var index = 0;
    while index < std::str::len(text) {
        if std::str::byte_at(text, index) == target {
            found = found + 1;
        }
        index = index + 1;
    }
    found
}

fn count_digits(in text: Str) -> Int {
    var found = 0;
    var index = 0;
    while index < std::str::len(text) {
        let byte = std::str::byte_at(text, index);
        if byte >= 48 && byte <= 57 {
            found = found + 1;
        }
        index = index + 1;
    }
    found
}

fn method_is_get(in text: Str) -> Int {
    if std::str::slice(text, 0, 3) == "GET" {
        1
    } else {
        0
    }
}

fn version_ok(in text: Str) -> Int {
    if std::str::slice(text, 14, 22) == "HTTP/1.1" {
        1
    } else {
        0
    }
}

fn score(in text: Str) -> Int {
    count_byte(text, 32)
        + count_byte(text, 47)
        + count_digits(text)
        + method_is_get(text)
        + version_ok(text)
}

fn main() -> Int {
    var total = 0;
    var round = 0;
    while round < 200 {
        total = total + score(line());
        round = round + 1;
    }
    total
}

// allocation — heap allocation and deallocation throughput over the ADR-0009
// allocator core (owned `String` + growable `Array[Int]`).
//
// Each round allocates two real heap buffers and frees them at scope end:
//   * a growable `Array[Int]` filled 0..COUNT by repeated `push` (which grows
//     the backing buffer by doubling — alloc-new + copy + free-old), then
//     scanned with `len`/`get`; the sum of 0..COUNT is COUNT*(COUNT-1)/2;
//   * an owned `String` built to COUNT bytes by repeated `push_byte` (the same
//     growth path over the byte buffer), then measured with `len`.
// A round's contribution is deterministic — array sum + string length — and the
// loop runs it ROUNDS times so the workload really exercises allocate/grow/free
// throughput (a leak would OOM; a double-free would abort). The observable
// result is one round's contribution (reassigned, not accumulated, so the exit
// stays a small documented byte): for COUNT = 16 the array sums to 120 and the
// string is 16 bytes, so `main` returns 136 (exit byte 136).

fn array_sum(take count: Int) -> Int {
    var xs = std::array::empty();
    var i = 0;
    while i < count {
        std::array::push(xs, i);
        i = i + 1;
    }
    var total = 0;
    var j = 0;
    while j < std::array::len(xs) {
        total = total + std::array::get(xs, j);
        j = j + 1;
    }
    total
}

fn string_len(take count: Int) -> Int {
    var s = std::string::empty();
    var i = 0;
    while i < count {
        std::string::push_byte(s, 65);
        i = i + 1;
    }
    std::string::len(s)
}

fn round(take count: Int) -> Int {
    array_sum(count) + string_len(count)
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 2000 {
        result = round(16);
        r = r + 1;
    }
    result
}

// map-lookup — keyed insert/lookup/churn throughput over the ADR-0011 hash
// map (`Map[Int, Int]`, the `tuo_rt_map_*` open-addressing table behind the
// three-word header).
//
// One round: insert COUNT entries (key i → value 3·i, growing the table by
// doubling through several thresholds), look every key back up summing the
// values modulo 1000, then remove the first half (the order-preserving
// removal path) and read the surviving entry count. A round's contribution is
// deterministic: for COUNT = 1000 the lookup sum is 3·999·1000/2 = 1_498_500,
// i.e. 500 after the running modulo, and 500 entries survive — 1000 total.
// The loop repeats the round so the workload really exercises hash, probe,
// growth, and removal throughput (a leak would OOM; a double-free would
// abort); the observable result is one round's contribution (reassigned, not
// accumulated): 1000, exit byte 1000 & 0xff = 232.

fn round(take count: Int) -> Int {
    var m = std::map::empty();
    var i = 0;
    while i < count {
        let _ = std::map::insert(m, i, i * 3);
        i = i + 1;
    }
    var hits = 0;
    var j = 0;
    while j < count {
        let value = match std::map::get(m, j) {
            Some { value } => value,
            None => 0,
        };
        hits = (hits + value) % 1000;
        j = j + 1;
    }
    var k = 0;
    while k < count / 2 {
        let _ = std::map::remove(m, k);
        k = k + 1;
    }
    hits + std::map::len(m)
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 50 {
        result = round(1000);
        r = r + 1;
    }
    result
}

// The file-io workload (ADR-0013): effect-crossing throughput over the OS
// boundary. Each round opens a scratch file for write, writes 15 sixteen-byte
// chunks (240 bytes), closes it, reopens it for read, reads it back
// byte-at-a-time (240 crossings of the read_byte seam), closes it, and
// removes it — so every ADR-0013 file primitive and the ADR-0006 descriptor
// seam are on the hot path. The C peer performs the identical sequence with
// open/write/read/close/unlink.
//
// round(15) returns the byte count read back, 240; main runs 200 rounds and
// returns the last round's count. Observable exit byte: 240 & 0xff = 240.

fn round(take chunks: Int) -> Int {
    let path = "file-io-bench.tmp";
    let fd = std::rt::open(path, 1);
    if fd < 0 {
        return 0 - 1;
    }
    var i = 0;
    while i < chunks {
        std::rt::write(fd, "0123456789abcdef");
        i = i + 1;
    }
    std::rt::close(fd);
    let rfd = std::rt::open(path, 0);
    if rfd < 0 {
        return 0 - 2;
    }
    var count = 0;
    var done = false;
    while !done {
        let b = std::rt::read_byte(rfd);
        if b < 0 {
            done = true;
        } else {
            count = count + 1;
        }
    }
    std::rt::close(rfd);
    std::rt::remove_file(path);
    count
}

fn main() -> Int {
    var result = 0;
    var r = 0;
    while r < 200 {
        result = round(15);
        r = r + 1;
    }
    result
}

